utputStream import java.util.Locale import java.util.zip.ZipInputStream private const val PREFS = "nhh" private const val GAME_DIR = "game" private const val GAME_EXE = "game_exe" private const val PREF_SETUP_IN_PROGRESS = "setup_in_progress" private enum class LauncherScreen { HOME, SETTINGS, CONTROLLER_TEST } private enum class SetupStage(val label: String) { EXTRACTING("Extracting the ZIP…"), ANALYSING("Analysing folders and subfolders…"), FOUND("Game executable found"), SELECT_EXE("Select the game executable"), BOOTSTRAP("Installing and setting up Winlator essentials"), FINISHING("Finishing runtime setup…") } class MainActivity : com.winlator.MainActivity() { override fun onCreate(savedInstanceState: Bundle?) { intent.putExtra("nhh_launcher", true) enableEdgeToEdge() super.onCreate(savedInstanceState) WinlatorRuntime.installCrashRecorder(this) setContent { NhhApp(applicationContext, this) } } } private val NhhExpressiveColorScheme = darkColorScheme( primary = Color(0xFFFF6B57), onPrimary = Color(0xFF2B0704), primaryContainer = Color(0xFF6B1E17), onPrimaryContainer = Color(0xFFFFDAD4), secondary = Color(0xFFFFC168), onSecondary = Color(0xFF2B1800), secondaryContainer = Color(0xFF55360A), onSecondaryContainer = Color(0xFFFFDDB0), tertiary = Color(0xFF9CD6A5), onTertiary = Color(0xFF0A3918), background = Color(0xFF140B0B), onBackground = Color(0xFFFCEBE7), surface = Color(0xFF1C1010), onSurface = Color(0xFFFCEBE7), surfaceContainerLowest = Color(0xFF110808), surfaceContainerLow = Color(0xFF211313), surfaceContainer = Color(0xFF291717), surfaceContainerHigh = Color(0xFF341E1E), surfaceContainerHighest = Color(0xFF422727), onSurfaceVariant = Color(0xFFD9C0BA), outline = Color(0xFF8C6B66), outlineVariant = Color(0xFF573B37), error = Color(0xFFFFB4AB) ) @Composable private fun NhhApp(context: Context, activity: MainActivity) { val prefs = remember { context.getSharedPreferences(PREFS, Context.MODE_PRIVATE) } var gameExe by remember { mutableStateOf(prefs.getString(GAME_EXE, null)) } var error by remember { mutableStateOf<String?>(null) } var currentScreen by remember { mutableStateOf(LauncherScreen.HOME) } var setupStage by remember { mutableStateOf<SetupStage?>(null) } var setupProgress by remember { mutableFloatStateOf(0f) } var setupDetail by remember { mutableStateOf("") } var exeChoices by remember { mutableStateOf<List<String>>(emptyList()) } var runtimeSettings by remember { mutableStateOf(LauncherRuntimeSettings()) } var settingsSaving by remember { mutableStateOf(false) } var settingsFeedback by remember { mutableStateOf<String?>(null) } var settingsError by remember { mutableStateOf<String?>(null) } val scope = rememberCoroutineScope() fun openSettings() { scope.launch { try { runtimeSettings = withContext(Dispatchers.Main) { WinlatorRuntime.loadSettings(activity, prefs) } settingsFeedback = null settingsError = null currentScreen = LauncherScreen.SETTINGS } catch (t: Throwable) { error = "Could not load runtime settings: ${t.message ?: "unknown error"}" } } } lateinit var picker: androidx.activity.result.ActivityResultLauncher<Array<String>> fun selectZip() { error = null currentScreen = LauncherScreen.HOME picker.launch(arrayOf("application/zip", "application/octet-stream", "application/x-zip-compressed")) } picker = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri: Uri? -> if (uri == null) return@rememberLauncherForActivityResult scope.launch { try { setupStage = SetupStage.EXTRACTING setupProgress = 0f setupDetail = "Opening ZIP…" val result = importGameZip( context, uri, onProgress = { stage, progress, detail -> setupStage = stage setupProgress = progress setupDetail = detail }, onNeedsExeSelection = { choices -> exeChoices = choices } ) if (result == null) return@launch prefs.edit() .putString(GAME_EXE, result.absolutePath) .putBoolean(PREF_SETUP_IN_PROGRESS, true) .commit() gameExe = result.absolutePath setupStage = SetupStage.BOOTSTRAP setupProgress = 0.02f setupDetail = "Installing system files and creating the NHH runtime…" WinlatorRuntime.prepare(activity, result, prefs) { progress, detail -> setupProgress = progress setupDetail = detail } prefs.edit().putBoolean(PREF_SETUP_IN_PROGRESS, false).apply() error = null setupStage = null } catch (t: Throwable) { prefs.edit().putBoolean(PREF_SETUP_IN_PROGRESS, false).apply() setupStage = null error = t.message ?: "Could not import and prepare the game." } } } MaterialTheme(colorScheme = NhhExpressiveColorScheme) { Surface(Modifier.fillMaxSize(), color = MaterialTheme.colorScheme.background) { when { setupStage == SetupStage.SELECT_EXE -> ExeSelectionScreen( choices = exeChoices, onSelect = { relativePath -> scope.launch { try { val selected = finalizeSelectedExe(context, relativePath) prefs.edit() .putString(GAME_EXE, selected.absolutePath) .putBoolean(PREF_SETUP_IN_PROGRESS, true) .commit() gameExe = selected.absolutePath setupStage = SetupStage.BOOTSTRAP setupProgress = 0.02f setupDetail = "Installing system files and creating the NHH runtime…" WinlatorRuntime.prepare(activity, selected, prefs) { progress, detail -> setupProgress = progress setupDetail = detail } prefs.edit().putBoolean(PREF_SETUP_IN_PROGRESS, false).apply() setupStage = null error = null } catch (t: Throwable) { prefs.edit().putBoolean(PREF_SETUP_IN_PROGRESS, false).apply() setupStage = null error = t.message ?: "Could not select the executable." } } }, onCancel = { setupStage = null error = "No game executable was selected." } ) setupStage != null -> SetupProgressScreen( stage = setupStage!!, progress = setupProgress, detail = setupDetail ) currentScreen == LauncherScreen.CONTROLLER_TEST -> ControllerTestScreen( onBack = { currentScreen = LauncherScreen.HOME }, onResetLayout = { WinlatorRuntime.resetControlsLayout(activity) } ) currentScreen == LauncherScreen.SETTINGS -> LauncherSettingsScreen( settings = runtimeSettings, isSaving = settingsSaving, feedback = settingsFeedback, error = settingsError, onChange = { runtimeSettings = it settingsFeedback = null settingsError = null }, onSave = { scope.launch { settingsSaving = true settingsFeedback = null settingsError = null try { withContext(Dispatchers.Main) { WinlatorRuntime.saveSettings(activity, prefs, runtimeSettings) } settingsFeedback = "Saved. Changes apply on next launch." } catch (t: Throwable) { settingsError = t.message ?: "Could not save runtime settings." } finally { settingsSaving = false } } }, onBack = { currentScreen = LauncherScreen.HOME }, onReimport = { selectZip() }, onResetControls = { WinlatorRuntime.resetControlsLayout(activity) settingsFeedback = "Restored default NHH Xbox on-screen layout." }, onOpenControllerTest = { currentScreen = LauncherScreen.CONTROLLER_TEST }, onShareReport = { WinlatorRuntime.shareLaunchReport(activity) } ) gameExe == null || !File(gameExe!!).isFile -> SetupScreen( error = error, onBack = { activity.finish() }, onSelectZip = { selectZip() } ) else -> MainMenu( gameExeName = File(gameExe!!).name, error = error, onSettings = { openSettings() }, onRun = { scope.launch { try { error = null setupStage = SetupStage.BOOTSTRAP setupProgress = 0f setupDetail = "Verifying Winlator runtime & NHH XInput profile…" WinlatorRuntime.ensureReady( activity, File(gameExe!!), prefs, onProgress = { progress, detail -> setupProgress = progress setupDetail = detail }, forceRebuild = false ) setupStage = null WinlatorRuntime.launchGame(activity, prefs) } catch (t: Throwable) { setupStage = null error = t.message ?: "Could not launch NHH." } } }, onEditControls = { scope.launch { try { error = null WinlatorRuntime.openControlsEditor(activity) } catch (t: Throwable) { error = t.message ?: "Could not open the controls editor." } } }, onTestController = { currentScreen = LauncherScreen.CONTROLLER_TEST }, onEnterDesktop = { scope.launch { try { error = null setupStage = SetupStage.BOOTSTRAP setupProgress = 0f setupDetail = "Preparing Winlator desktop environment…" WinlatorRuntime.ensureReady( activity, File(gameExe!!), prefs, onProgress = { progress, detail -> setupProgress = progress setupDetail = detail }, forceRebuild = false ) setupStage = null WinlatorRuntime.enterDesktop(activity, prefs) } catch (t: Throwable) { setupStage = null error = t.message ?: "Could not open container desktop." } } } ) } } } } @Composable private fun MainMenu( gameExeName: String, error: String?, onSettings: () -> Unit, onRun: () -> Unit, onEditControls: () -> Unit, onTestController: () -> Unit, onEnterDesktop: () -> Unit ) { Column( modifier = Modifier .fillMaxSize() .statusBarsPadding() .navigationBarsPadding() .verticalScroll(rememberScrollState()) .padding(horizontal = 20.dp, vertical = 16.dp), verticalArrangement = Arrangement.spacedBy(16.dp) ) { // Expressive Top Header Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) { Image( painter = painterResource(R.drawable.nhh_logo), contentDescription = "No Heroes Here", modifier = Modifier.size(54.dp).clip(RoundedCornerShape(18.dp)), contentScale = ContentScale.Crop ) Spacer(Modifier.width(14.dp)) Column(Modifier.weight(1f)) { Text( "No Heroes Here", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.ExtraBold ) Text( "XInput Ready • $gameExeName", style = MaterialTheme.typography.labelLarge, color = MaterialTheme.colorScheme.onSurfaceVariant ) } FilledTonalIconButton( onClick = onSettings, modifier = Modifier.size(48.dp) ) { Icon(Icons.Default.Settings, contentDescription = "Settings") } } // Expressive Hero Banner Card Box( modifier = Modifier .fillMaxWidth() .height(210.dp) .clip(RoundedCornerShape(28.dp)) ) { Image( painter = painterResource(R.drawable.nhh_banner), contentDescription = "No Heroes Here", modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop ) Box( modifier = Modifier .fillMaxSize() .background( Brush.verticalGradient( colors = listOf(Color.Transparent, Color(0xCC140B0B)), startY = 120f ) ) ) Row( modifier = Modifier .align(Alignment.BottomStart) .padding(16.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp) ) { Surface( shape = CircleShape, color = Color(0xE6225E30) ) { Row( Modifier.padding(horizontal = 12.dp, vertical = 6.dp), verticalAlignment = Alignment.CenterVertically ) { Icon( Icons.Default.CheckCircle, contentDescription = null, tint = Color(0xFFB7F5C4), modifier = Modifier.size(16.dp) ) Spacer(Modifier.width(6.dp)) Text( "READY", style = MaterialTheme.typography.labelLarge, color = Color(0xFFB7F5C4), fontWeight = FontWeight.Bold ) } } Surface( shape = CircleShape, color = MaterialTheme.colorScheme.surfaceContainerHigh.copy(alpha = 0.88f) ) { Text( "Xbox Layout Loaded", modifier = Modifier.padding(horizontal = 12.dp, vertical = 6.dp), style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurface ) } } } // Primary Expressive Pill CTA: RUN GAME Button( onClick = onRun, modifier = Modifier.fillMaxWidth().height(68.dp), shape = RoundedCornerShape(32.dp), elevation = ButtonDefaults.buttonElevation(defaultElevation = 4.dp) ) { Icon(Icons.Default.PlayArrow, contentDescription = null, modifier = Modifier.size(28.dp)) Spacer(Modifier.width(10.dp)) Text( "RUN GAME", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.ExtraBold ) } // Split Secondary Expressive Actions: Edit Controls & Controller Test Mode Row( Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp) ) { FilledTonalButton( onClick = onEditControls, modifier = Modifier.weight(1f).height(58.dp), shape = RoundedCornerShape(22.dp) ) { Icon(Icons.Default.Gamepad, contentDescription = null) Spacer(Modifier.width(8.dp)) Text("Edit Layout", fontWeight = FontWeight.Bold) } FilledTonalButton( onClick = onTestController, modifier = Modifier.weight(1f).height(58.dp), shape = RoundedCornerShape(22.dp) ) { Icon(Icons.Default.SportsEsports, contentDescription = null) Spacer(Modifier.width(8.dp)) Text("Test Pad", fontWeight = FontWeight.Bold) } } // Dedicated ENTER DESKTOP Button (install additional drivers, Mono, VC++, etc.) OutlinedButton( onClick = onEnterDesktop, modifier = Modifier.fillMaxWidth().height(58.dp), shape = RoundedCornerShape(22.dp), border = BorderStroke(1.5.dp, MaterialTheme.colorScheme.secondary) ) { Icon( Icons.Default.DesktopWindows, contentDescription = null, tint = MaterialTheme.colorScheme.secondary ) Spacer(Modifier.width(10.dp)) Text( "ENTER DESKTOP", style = MaterialTheme.typography.titleMedium, color = MaterialTheme.colorScheme.secondary, fontWeight = FontWeight.Bold ) } // Pre-loaded NHH Xbox Control Quick Reference Card ElevatedCard( modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(24.dp), colors = CardDefaults.elevatedCardColors( containerColor = MaterialTheme.colorScheme.surfaceContainer ) ) { Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) { Row(verticalAlignment = Alignment.CenterVertically) { Icon( Icons.Default.Tune, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp) ) Spacer(Modifier.width(8.dp)) Text( "NHH XBOX CONTROLS (PRE-LOADED)", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary ) } ControlHintRow("L-Stick / D-Pad", "Move, climb ladders & menus") ControlHintRow("A / B", "Jump (Confirm) • Throw (Back)") ControlHintRow("X / Y", "Interact / Work • Dash / Sprint") ControlHintRow("RB / RT", "Fire cannon / Quick-throw") ControlHintRow("LB / LT", "Switch character (Solo 2P)") ControlHintRow("Menu (Start)", "Pause / Controller settings") } } if (!error.isNullOrBlank()) { Card( modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(18.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.errorContainer) ) { Text( error, modifier = Modifier.padding(14.dp), color = MaterialTheme.colorScheme.onErrorContainer ) } } } } @Composable private fun ControlHintRow(button: String, action: String) { Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) { Text( button, modifier = Modifier.width(126.dp), style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.secondary ) Text( action, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant ) } } @Composable private fun SetupProgressScreen(stage: SetupStage, progress: Float, detail: String) { Column( Modifier .fillMaxSize() .statusBarsPadding() .navigationBarsPadding() .padding(20.dp), verticalArrangement = Arrangement.spacedBy(16.dp) ) { Text("Setting up No Heroes Here", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold) Image( painterResource(R.drawable.nhh_banner), null, Modifier.fillMaxWidth().height(200.dp).clip(RoundedCornerShape(24.dp)), contentScale = ContentScale.Crop ) ElevatedCard( Modifier.fillMaxWidth(), shape = RoundedCornerShape(24.dp), colors = CardDefaults.elevatedCardColors(containerColor = MaterialTheme.colorScheme.surfaceContainer) ) { Column(Modifier.padding(20.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) { Text( if (stage == SetupStage.BOOTSTRAP || stage == SetupStage.FINISHING) "Preparing Winlator Runtime" else "Installing Game Files", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold ) Text(detail.ifBlank { stage.label }, color = MaterialTheme.colorScheme.onSurfaceVariant) LinearProgressIndicator( progress = { progress.coerceIn(0f, 1f) }, modifier = Modifier.fillMaxWidth().height(8.dp).clip(CircleShape) ) Text( "${(progress.coerceIn(0f, 1f) * 100).toInt()}%", style = MaterialTheme.typography.titleMedium, color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold ) } } } } @Composable private fun SetupScreen(error: String?, onBack: () -> Unit, onSelectZip: () -> Unit) { Column( Modifier .fillMaxSize() .statusBarsPadding() .navigationBarsPadding() .padding(20.dp), verticalArrangement = Arrangement.spacedBy(16.dp) ) { Row(verticalAlignment = Alignment.CenterVertically) { IconButton(onClick = onBack) { Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back") } Text("No Heroes Here Setup", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold) } Image( painterResource(R.drawable.nhh_banner), null, Modifier.fillMaxWidth().height(220.dp).clip(RoundedCornerShape(26.dp)), contentScale = ContentScale.Crop ) ElevatedCard( Modifier.fillMaxWidth(), shape = RoundedCornerShape(24.dp), colors = CardDefaults.elevatedCardColors(containerColor = MaterialTheme.colorScheme.surfaceContainer) ) { Column(Modifier.padding(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) { Text("Import Game Archive", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold) Text( "Select your No Heroes Here ZIP. The launcher will extract it, bootstrap Winlator, and pre-load the Xbox controller layout automatically.", color = MaterialTheme.colorScheme.onSurfaceVariant ) Button( onClick = onSelectZip, modifier = Modifier.fillMaxWidth().height(58.dp), shape = RoundedCornerShape(28.dp) ) { Icon(Icons.Default.FolderOpen, null) Spacer(Modifier.width(8.dp)) Text("SELECT GAME ZIP", fontWeight = FontWeight.Bold) } if (!error.isNullOrBlank()) Text(error, color = MaterialTheme.colorScheme.error) } } } } private suspend fun importGameZip( context: Context, uri: Uri, onProgress: suspend (SetupStage, Float, String) -> Unit, onNeedsExeSelection: (List<String>) -> Unit ): File? = withContext(Dispatchers.IO) { val stagingDir = File(context.filesDir, "$GAME_DIR.staging") if (stagingDir.exists()) stagingDir.deleteRecursively() stagingDir.mkdirs() suspend fun progress(stage: SetupStage, value: Float, detail: String = "") { withContext(Dispatchers.Main.immediate) { onProgress(stage, value, detail) } } try { progress(SetupStage.EXTRACTING, 0f, "Opening ZIP…") var totalKnownBytes = 0L var extractedBytes = 0L var lastUiUpdateNanos = 0L var lastUiBytes = 0L val input = withContext(Dispatchers.Main.immediate) { context.contentResolver.openInputStream(uri) } ?: throw IllegalArgumentException("Could not read the selected ZIP.") input.use { ZipInputStream(it.buffered(1024 * 1024)).use { zip -> val root = stagingDir.canonicalFile val buffer = ByteArray(1024 * 1024) var entry = zip.nextEntry while (entry != null) { val entryName = entry.name val target = File(stagingDir, entryName).canonicalFile if (!target.path.startsWith(root.path + File.separator) && target != root) { throw IllegalArgumentException("Invalid ZIP path.") } if (entry.isDirectory) { target.mkdirs() } else { target.parentFile?.mkdirs() FileOutputStream(target, false).buffered(1024 * 1024).use { output -> while (true) { val read = zip.read(buffer) if (read < 0) break output.write(buffer, 0, read) extractedBytes += read } } if (entry.size > 0) totalKnownBytes += entry.size } val now = System.nanoTime() if (now - lastUiUpdateNanos >= 120_000_000L || extractedBytes - lastUiBytes >= 4L * 1024 * 1024L) { lastUiUpdateNanos = now lastUiBytes = extractedBytes val fraction = if (totalKnownBytes > 0L) { (extractedBytes.toDouble() / totalKnownBytes.toDouble()).toFloat().coerceIn(0f, 1f) } else 0f progress(SetupStage.EXTRACTING, fraction, "${formatBytes(extractedBytes)} • $entryName") } zip.closeEntry() entry = zip.nextEntry } } } progress(SetupStage.EXTRACTING, 1f, "Extraction complete") progress(SetupStage.ANALYSING, 0f, "Searching folders and subfolders…") val executables = stagingDir.walkTopDown().filter { it.isFile && it.extension.equals("exe", ignoreCase = true) }.toList() val preferred = executables.firstOrNull { it.name.lowercase(Locale.ROOT) == "nhh.exe" } ?: executables.firstOrNull { it.name.lowercase(Locale.ROOT) == "nhh_build.exe" } progress(SetupStage.ANALYSING, 1f, "${executables.size} executable(s) found") if (preferred == null) { if (executables.isEmpty()) { throw IllegalArgumentException("No .exe file was found in the extracted game files.") } withContext(Dispatchers.Main.immediate) { onNeedsExeSelection(executables.map { it.relativeTo(stagingDir).path }) } progress(SetupStage.SELECT_EXE, 1f, "Choose the game executable") return@withContext null } progress(SetupStage.FOUND, 1f, "${preferred.name} found") finalizeGameInstall(context, preferred.relativeTo(stagingDir).path) } catch (t: Throwable) { stagingDir.deleteRecursively() throw t } } private fun formatBytes(bytes: Long): String { val mb = bytes / (1024.0 * 1024.0) return if (mb < 1024.0) String.format(Locale.US, "%.1f MB", mb) else String.format(Locale.US, "%.2f GB", mb / 1024.0) } private suspend fun finalizeSelectedExe(context: Context, relativePath: String): File = withContext(Dispatchers.IO) { finalizeGameInstall(context, relativePath) } private fun finalizeGameInstall(context: Context, relativePath: String): File { val stagingDir = File(context.filesDir, "$GAME_DIR.staging") val gameDir = File(context.filesDir, GAME_DIR) val selected = File(stagingDir, relativePath).canonicalFile val root = stagingDir.canonicalFile if (!selected.path.startsWith(root.path + File.separator) || !selected.isFile) { throw IllegalArgumentException("Invalid executable selection.") } if (gameDir.exists()) gameDir.deleteRecursively() if (!stagingDir.renameTo(gameDir)) { throw IllegalStateException("Could not finalize the extracted game files.") } return File(gameDir, relativePath).takeIf { it.isFile } ?: throw IllegalStateException("The selected executable disappeared while finalizing the install.") } @Composable private fun ExeSelectionScreen(choices: List<String>, onSelect: (String) -> Unit, onCancel: () -> Unit) { Column( Modifier .fillMaxSize() .statusBarsPadding() .navigationBarsPadding() .padding(24.dp) ) { Text("Select game executable", style = MaterialTheme.typography.headlineMedium, fontWeight = FontWeight.Bold) Spacer(Modifier.height(8.dp)) Text( "NHH.exe or NHH_build.exe was not found automatically. Select the correct .exe below.", color = MaterialTheme.colorScheme.onSurfaceVariant ) Spacer(Modifier.height(18.dp)) LazyColumn(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(10.dp)) { items(choices) { path -> FilledTonalButton( onClick = { onSelect(path) }, modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(16.dp) ) { Text(path) } } } Spacer(Modifier.height(12.dp)) TextButton(onClick = onCancel, modifier = Modifier.fillMaxWidth()) { Text("CANCEL") } } }